// Returns name hash, see common:/data/levels/rdr3/mapzones.meta
// 
// type (-1 matches any type):
// class CMapZone
// {
// public:
// 	enum class Type
// 	{
// 		STATE,
// 		TOWN,
// 		LAKE,
// 		RIVER,
// 		OIL_SPILL,
// 		SWAMP,
// 		OCEAN,
// 		CREEK,
// 		POND,
// 		GLACIER,
// 		DISTRICT,
// 		TEXT_PRINTED,
// 		TEXT_WRITTEN
// 	};
// };
// 
